To enhance readability, we commonly use the superscript $+$ to indicate a one-fold forward-shift of a variable, whereas higher-order forward-shifts and backward-shifts are written using bracketed subscripts.
    Thus, for $\alpha \geq 0$, $u_{[\alpha]}$ denotes the $\alpha$-th forward-shift of the variable $u$, and $u_{[-\alpha]}$ its $\alpha$-th backward-shift.
    The corresponding forward- and backward-shift operators, denoted by $\delta^{\alpha}$ and $\delta^{-\alpha}$, act on variables as well as on functions; see, e.g., \cite{DiwoldKolarSchoberl:2020} for details.
    If a variable consists of several components, i.e., $y = (y^1,\ldots,y^m)$, we write $y_{[\alpha]} = (y^1_{[\alpha]},\ldots,y^m_{[\alpha]})$.\\
    Shifts of different orders for the individual components are represented compactly by multi-indices. 
    For two multi-indices $S_1 = (s_{1,1},\ldots,s_{1,m})$ and $S_2 = (s_{2,1},\ldots,s_{2,m})$, $y_{[-S_1]}$ and $y_{[S_2]}$ denote the corresponding backward- and forward-shifts of the individual components of $y$. Furthermore, $y_{[-S_1,S_2]}$ is an abbreviation for $y$ together with its backward-shifts up to the orders $S_1$ and its forward-shifts up to the orders $S_2$.
    We write $S_1 \leq S_2$ if $s_{1,j} \leq s_{2,j}$ holds for all $j=1,\ldots,m$, and $y^j_{[s_{1,j},s_{2,j}]}$ is defined to be empty whenever $s_{1,j} > s_{2,j}$.
    Addition and subtraction of two multi-indices $S_1$ and $S_2$, as well as of a multi-index $S_1$ and a scalar $a$, are performed component-wise, i.e.,
    \begin{equation*}
      \begin{aligned}
        S_1 \pm S_2 &= (s_{1,1} \pm s_{2,1},\ldots,s_{1,m} \pm s_{2,m}), \\
        S_1 \pm a   &= (s_{1,1} \pm a,\ldots,s_{1,m} \pm a)\,.
      \end{aligned}
    \end{equation*}
    The sum over all components of a multi-index $S_1$ is denoted by
    \begin{equation*}
      \#S_1 = \sum_{j=1}^{m} s_{1,j}\,.
    \end{equation*}

\label{def:flatness}The system \eqref{eq:sysEq} is said to be flat around an equilibrium $(x_{0},u_{0})$, if the $n+m$ coordinate functions $x$ and $u$ can be expressed locally by an $m$-tuple of functions
		\begin{equation}
			y^{j}=\varphi^{j}(\zeta_{[-Q_1,-1]},x,u,u_{[1,Q_2]})\,,\quad\,j=1,\ldots,m\label{eq:flat_output}
		\end{equation}
		called the flat output, and its backward- and forward-shifts up to some finite order, i.e.
    	\begin{equation}\label{eq:flat_param}
    		\begin{aligned}
    			x&=F_{x}(y_{[-R_1,R_2-1]})\,, &\; u&=F_{u}(y_{[-R_1,R_2]})\,.
    		\end{aligned}
    	\end{equation}
        \vspace{-0.3cm}

\label{def:backward-flatness}The system \eqref{eq:sysEq} is said
		to be backward-flat around an equilibrium $(x_{0},u_{0})$, if the
		$n+m$ coordinate functions $x$ and $u$ can be expressed locally
		by an $m$-tuple of functions
		\begin{equation*}
			y^{j}=\varphi^{j}(\zeta_{[-Q_1,-1]},x,u)\,,\quad j=1,\ldots,m\label{eq:backward-flat_output}
		\end{equation*}
		called the backward-flat output, and its backward-shifts up to some finite order, i.e.
        \begin{equation}\label{eq:backward_flat_param}
    		\begin{aligned}
    			x&=F_{x}(y_{[-R_1,-1]})\,, &\; u&=F_{u}(y_{[-R_1,0]})\,.
    		\end{aligned}
	    \end{equation}
        \vspace{-0.3cm}

By defining $\tilde y=(y_p^+, \ldots, y_1^+)$ as the new flat output, the backward-shifts $\tilde y_{p,[-1]}, \tilde y_{p-1,[-1]},\dots,\tilde y_{1,[-1]}$ now represent components of the state, i.e.,
        \begin{equation*}
            \begin{aligned}
            {x} & =({x}_{p},{x}_{p-1}\dots,{x}_{1})\\
            & =(\tilde y_{p,[-1]},(\tilde y_{p-1,[-1]},\hat{x}_{p-1}),\dots,(\tilde y_{1,[-1]},\hat{x}_{1}))\,.
            \end{aligned}
        \end{equation*}
        Therefore, by the rank condition \eqref{eq:rank_cond_disc} for $k=p-1$, the topmost set of equations
        \begin{equation*}
            \tilde y_p = \tilde y_{p,[-1]} + T_s f_p(\tilde y_p, \tilde y_{p-1}, \hat{x}_{p-1}^+, u_{p-1})
        \end{equation*}
        can be solved for $(\hat{x}_{p-1}^+,u_{p-1})$ as functions of $\tilde y_{p,[-1]}$, $\tilde y_p$, and $\tilde y_{p-1}$. To parameterize the non-shifted state variables $\hat{x}_{p-1}$, an additional backward-shift is required. Consequently, $\hat{x}_{p-1}$ depends on $\tilde y_{p,[-2]}$, $\tilde y_{p,[-1]}$, and $\tilde y_{p-1,[-1]}$. Since the remaining components of $x_{p-1}$ are given by $\tilde y_{p-1,[-1]}$, the variables $(x_{p-1},u_{p-1})$ are completely parameterized by $\tilde y_{p,[-2]}, \tilde y_{p,[-1]}, \tilde y_p, \tilde y_{p-1,[-2]}, \tilde y_{p-1,[-1]}$.
        Proceeding recursively with the remaining blocks of equations ultimately yields a parameterization of the form~\eqref{eq:backward_flat_param}.
